	if err != nil {
		return err
	}

	obj := make(map[string]interface{})
	toolKeyProp, err := expandDialogflowToolToolKey(d.Get("tool_key"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("tool_key"); !tpgresource.IsEmptyValue(reflect.ValueOf(toolKeyProp)) && (ok || !reflect.DeepEqual(v, toolKeyProp)) {
		obj["toolKey"] = toolKeyProp
	}
	displayNameProp, err := expandDialogflowToolDisplayName(d.Get("display_name"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("display_name"); !tpgresource.IsEmptyValue(reflect.ValueOf(displayNameProp)) && (ok || !reflect.DeepEqual(v, displayNameProp)) {
		obj["displayName"] = displayNameProp
	}
	descriptionProp, err := expandDialogflowToolDescription(d.Get("description"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("description"); !tpgresource.IsEmptyValue(reflect.ValueOf(descriptionProp)) && (ok || !reflect.DeepEqual(v, descriptionProp)) {
		obj["description"] = descriptionProp
	}
	actionConfirmationRequirementProp, err := expandDialogflowToolActionConfirmationRequirement(d.Get("action_confirmation_requirement"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("action_confirmation_requirement"); !tpgresource.IsEmptyValue(reflect.ValueOf(actionConfirmationRequirementProp)) && (ok || !reflect.DeepEqual(v, actionConfirmationRequirementProp)) {
		obj["actionConfirmationRequirement"] = actionConfirmationRequirementProp
	}
	openApiSpecProp, err := expandDialogflowToolOpenApiSpec(d.Get("open_api_spec"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("open_api_spec"); !tpgresource.IsEmptyValue(reflect.ValueOf(openApiSpecProp)) && (ok || !reflect.DeepEqual(v, openApiSpecProp)) {
		obj["openApiSpec"] = openApiSpecProp
	}
	functionSpecProp, err := expandDialogflowToolFunctionSpec(d.Get("function_spec"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("function_spec"); !tpgresource.IsEmptyValue(reflect.ValueOf(functionSpecProp)) && (ok || !reflect.DeepEqual(v, functionSpecProp)) {
		obj["functionSpec"] = functionSpecProp
	}
	connectorSpecProp, err := expandDialogflowToolConnectorSpec(d.Get("connector_spec"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("connector_spec"); !tpgresource.IsEmptyValue(reflect.ValueOf(connectorSpecProp)) && (ok || !reflect.DeepEqual(v, connectorSpecProp)) {
		obj["connectorSpec"] = connectorSpecProp
	}
	toolIdProp, err := expandDialogflowToolToolId(d.Get("tool_id"), d, config)
	if err != nil {
		return err
	} else if v, ok := d.GetOkExists("tool_id"); !tpgresource.IsEmptyValue(reflect.ValueOf(toolIdProp)) && (ok || !reflect.DeepEqual(v, toolIdProp)) {
		obj["toolId"] = toolIdProp
	}

	url, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"projects/{{project}}/locations/{{location}}/tools?toolId={{tool_id}}")
	if err != nil {
		return err
	}

	log.Printf("[DEBUG] Creating new Tool: %#v", obj)
	billingProject := ""

	project, err := tpgresource.GetProject(d, config)
	if err != nil {
		return fmt.Errorf("Error fetching project for Tool: %s", err)
	}
	billingProject = project

	// err == nil indicates that the billing_project value was found
	if bp, err := tpgresource.GetBillingProject(d, config); err == nil {
		billingProject = bp
	}

	headers := make(http.Header)
	location := d.Get("location").(string)
